assignments.value:
={{    
    {
  message: {
    id: String($json["message_id"]),
    channel: $json["channel_id"],
    timestamp: $json["created_at"]
  },
  content: $json["content"]
}
}}

={{
(() => {
  const base = $json.message;
  // --- converter sicuro -> Telegram Markdown V2 ---
  const RE_CODE      = /```[\s\S]*?```|`[^`]*?`/g;
  const RE_BOLD      = /\*\*([\s\S]+?)\*\*|__([\s\S]+?)__/g;
  const RE_ITAL_STAR = /(^|[^*])\*([^\n*]+?)\*(?!\*)/g;
  const RE_ITAL_UND  = /(^|[^_])_([^\n_]+?)_(?!_)/g;
  const RE_STRK      = /~([^~]+?)~/g;
  const RE_RSRV      = /[_*\[\]()~`>#+\-=|{}.!\\]/g;
  const PLACE = (i) => `\u0000${i}\u0000`;
  const esc   = (s) => String(s).replace(RE_RSRV, '\\$&');
  const safe  = (x) => (x == null ? '' : String(x));
  const stash = (txt, re, fn, bag) =>
    txt.replace(re, function () {
      const seg = fn.apply(null, arguments);
      const val = seg == null ? esc(arguments[0]) : String(seg);
      bag.push(val);
      return PLACE(bag.length - 1);
    });

  let out = String(base);
  const bag = [];

  out = stash(out, RE_CODE, (m) => m, bag);
  out = stash(out, RE_BOLD, (_m, g1, g2) => {
    const txt = safe(g1 ?? g2).trim();
    return txt ? `*${esc(txt)}*` : esc(_m);
  }, bag);
  out = stash(out, RE_ITAL_STAR, (_m, pre, g) => {
    const txt = safe(g).trim();
    return txt ? `${safe(pre)}_${esc(txt)}_` : esc(_m);
  }, bag);
  out = stash(out, RE_ITAL_UND, (_m, pre, g) => {
    const txt = safe(g).trim();
    return txt ? `${safe(pre)}_${esc(txt)}_` : esc(_m);
  }, bag);
  out = stash(out, RE_STRK, (_m, g) => {
    const txt = safe(g).trim();
    return txt ? `~${esc(txt)}~` : esc(_m);
  }, bag);

  out = esc(out).replace(/(^|\n)-/g, '$1\\-');
  out = out.replace(/\u0000(\d+)\u0000/g, (_m, i) => safe(bag[Number(i)]));
  out = out.replace(/(^|[^\\])__($|[^_])/g, (_m, a, b) => `${a}\\_\\_${b}`);

  // ultima rete di sicurezza: rimuovi "undefined" letterali residui (solo se proprio serve)
  out = out.replace(/undefined/g, '');

  return out;
})()
}}

conditions.leftValue:
={{
  (() => {
    const t = $json.last_vocal_ts;
    const diff = DateTime.now().diff(DateTime.fromISO(t), "hours").hours;
    return isNaN(diff) ? 1 : diff;
  })()
}}
